from itertools import chain, islice
from pathlib import Path

def iter_lines(paths: list[Path]) -> Iterator[str]:
    def _one(path: Path):
        with path.open(encoding="utf-8") as handle:
            for line in handle:
                text = line.strip()
                if text:
                    yield text
    return chain.from_iterable(_one(path) for path in paths)

def by_prefix(lines: list[str]) -> dict[str, list[str]]:
    buckets: dict[str, list[str]] = {}
    for line in lines:
        prefix = line.split("-", 1)[0]
        buckets.setdefault(prefix, []).append(line)
    return buckets
```

