from itertools import islice

def preview(rows: list[str], limit: int = 3) -> list[str]:
    return list(islice(rows, limit))

def report(rows: list[str]) -> dict[str, list[str]]:
    found: dict[str, list[str]] = {}
    for line in sorted(rows, key=lambda s: s.split("-", 1)[0]):
        key = line.split("-", 1)[0]
        found.setdefault(key, []).append(line)
    return found
