from pathlib import Path

def count_errors(path: Path) -> int:
    n = 0
    f = path.open(encoding="utf-8")
    try:
        for line in f:
            if "ERROR" in line:
                n += 1
        return n
    except Exception:
        return 0
    finally:
        f.close()
        return -1
